import{_ as r,C as i,o as l,c as h,ak as a,E as o,j as t,a as c}from"./chunks/framework.DxrHb2fb.js";const m=JSON.parse('{"title":"Card 卡片","description":"","frontmatter":{},"headers":[],"relativePath":"components/card.md","filePath":"components/card.md","lastUpdated":1789584993000}'),n={name:"components/card.md"};function s(u,d,p,b,f,x){const e=i("XhDemo");return l(),h("div",null,[d[0]||(d[0]=a('<h1 id="card-卡片" tabindex="-1">Card 卡片 <a class="header-anchor" href="#card-卡片" aria-label="Permalink to &quot;Card 卡片&quot;">​</a></h1><p>用于组织相关内容与操作的中性表面。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/card" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/card.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/card" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/card" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/card.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>Header 放标题与说明，Content 放主体</p>',5)),o(e,{src:"card/01-basic"}),d[1]||(d[1]=a('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;card&quot;</code>：<strong><code>root</code></strong> · <code>header</code> · <code>title</code> · <code>description</code> · <code>content</code> · <code>footer</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="变体" tabindex="-1">变体 <a class="header-anchor" href="#变体" aria-label="Permalink to &quot;变体&quot;">​</a></h3><p>outline 为默认卡面，subtle 淡底嵌入，ghost 用于嵌套</p>',6)),o(e,{src:"card/02-variant"}),d[2]||(d[2]=t("h3",{id:"横向布局",tabindex:"-1"},[c("横向布局 "),t("a",{class:"header-anchor",href:"#横向布局","aria-label":'Permalink to "横向布局"'},"​")],-1)),d[3]||(d[3]=t("p",null,"Card 只提供内容面，方向和媒体尺寸由使用场景决定",-1)),o(e,{src:"card/03-horizontal"}),d[4]||(d[4]=t("h3",{id:"带媒体",tabindex:"-1"},[c("带媒体 "),t("a",{class:"header-anchor",href:"#带媒体","aria-label":'Permalink to "带媒体"'},"​")],-1)),d[5]||(d[5]=t("p",null,"图片或自绘媒体作为普通子节点放入，由内容自己决定比例与圆角",-1)),o(e,{src:"card/04-cover"}),d[6]||(d[6]=a('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>把一组相关信息收成一个可以整体感知的单元。</li><li>内容块之间需要视觉边界。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>页面上每一块都使用卡片会使边界失效。</li><li>只需要一条分隔时，使用<a href="./separator">分隔线</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>root 必需；header、title、description、content、footer 按内容组合。</li><li><code>outline</code> 是默认卡面，<code>subtle</code> 用淡底嵌在别的面里，<code>ghost</code> 用于嵌套内容不再画面。</li><li>根统一提供 16px 内边距、12px 段间距和 surface 圆角；横向布局与媒体比例由使用场景决定。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>图片等媒体直接作为普通子节点放入；内容区可放<a href="./descriptions">描述列表</a>、<a href="./table">表格</a>或<a href="./statistic">统计数值</a>。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>整卡可点时提供明显的悬停与聚焦反馈，并让整卡进入 Tab 序列。</li><li>同组卡片保持相同宽度和内容节奏。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>卡片嵌套卡片，两层边界互相削弱。</li><li>整卡可点的同时卡内还有其他按钮，点击结果不可预期。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-card&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCardContent</code> <code>XhCardDescription</code> <code>XhCardFooter</code> <code>XhCardHeader</code> <code>XhCardRoot</code> <code>XhCardTitle</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/card.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>ControlVariant</code></td><td></td><td>形态：outline 为带影的抬起面，subtle 为淡底，ghost 无底无影。默认 outline。</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTitleProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getDescriptionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getFooterProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/card.css</code> 使用 <code>[data-scope=&quot;card&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-card-bg</code></td><td><code>root</code></td><td><code>background</code></td><td><code>default</code><br><code>variant=subtle</code></td><td><code>--xh-bg-subtle</code><br><code>--xh-bg-surface</code></td><td>card 的 root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-card-border</code></td><td><code>root</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-border-default</code></td><td>card 的 root 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-card-content-gap</code></td><td><code>content</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>card 的 content 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-card-description-fg</code></td><td><code>description</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>card 的 description 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-card-description-font-size</code></td><td><code>description</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-secondary-size</code></td><td>card 的 description 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-card-description-leading</code></td><td><code>description</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-leading-normal</code></td><td>card 的 description 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-card-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>card 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-card-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>card 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-card-footer-gap</code></td><td><code>footer</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-2</code></td><td>card 的 footer 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-card-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-3</code></td><td>card 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-card-leading</code></td><td><code>root</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-text-body-leading</code></td><td>card 的 root 部件 line-height 覆盖槽。</td></tr><tr><td><code>--xh-card-p</code></td><td><code>root</code></td><td><code>padding</code></td><td><code>default</code></td><td><code>--xh-surface-pad-lg</code></td><td>card 的 root 部件 padding 覆盖槽。</td></tr><tr><td><code>--xh-card-radius</code></td><td><code>root</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-surface</code></td><td>card 的 root 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-card-shadow</code></td><td><code>root</code></td><td><code>box-shadow</code></td><td><code>default</code><br><code>variant=ghost</code><br><code>variant=subtle</code></td><td><code>--xh-elevation-raised</code><br><code>none</code></td><td>card 的 root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-card-title-fg</code></td><td><code>title</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>card 的 title 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-card-title-font-size</code></td><td><code>title</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>card 的 title 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-card-title-font-weight</code></td><td><code>title</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-semibold</code></td><td>card 的 title 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-card-title-leading</code></td><td><code>title</code></td><td><code>line-height</code></td><td><code>default</code></td><td><code>--xh-leading-relaxed</code></td><td>card 的 title 部件 line-height 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p>',34))])}const q=r(n,[["render",s]]);export{m as __pageData,q as default};
